namespace sv_e8e96385e1b844f4b6e1825f7f37056e.Client;

// Serializable DTO used to pass authenticated user info from server to WebAssembly via PersistentComponentState.
public sealed class UserInfo
{
    public required string Email { get; set; }
    public required string[] Roles { get; set; }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_e8e96385e1b844f4b6e1825f7f37056e.Auth;

/// <summary>
/// Server-side AuthenticationStateProvider that always returns a hardcoded authenticated user.
/// </summary>
public sealed class HardcodedAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly Task<AuthenticationState> _authState = Task.FromResult(CreateState());

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _authState;

    private static AuthenticationState CreateState()
    {
        var claims = new[]
        {
            new Claim(ClaimTypes.Name, "bob@example.com"),
            new Claim(ClaimTypes.Email, "bob@example.com"),
            new Claim(ClaimTypes.Role, "User"),
            new Claim(ClaimTypes.Role, "Editor"),
        };

        var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
        var principal = new ClaimsPrincipal(identity);
        return new AuthenticationState(principal);
    }
}

using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;
using sv_e8e96385e1b844f4b6e1825f7f37056e.Client;
using System.Security.Claims;

namespace sv_e8e96385e1b844f4b6e1825f7f37056e.Auth;

/// <summary>
/// Subscribes to AuthenticationStateProvider and persists user info into PersistentComponentState
/// so the WebAssembly client can reconstruct the ClaimsPrincipal after the WASM runtime activates.
/// </summary>
public sealed class PersistingAuthenticationStateProvider : IHostEnvironmentAuthenticationStateProvider, IDisposable
{
    private readonly PersistentComponentState _persistentComponentState;
    private readonly AuthenticationStateProvider _authenticationStateProvider;
    private PersistingComponentStateSubscription _subscription;
    private Task<AuthenticationState>? _authenticationStateTask;

    public PersistingAuthenticationStateProvider(
        PersistentComponentState persistentComponentState,
        AuthenticationStateProvider authenticationStateProvider)
    {
        _persistentComponentState = persistentComponentState;
        _authenticationStateProvider = authenticationStateProvider;

        AuthenticationStateChanged += OnAuthenticationStateChanged;
        _subscription = _persistentComponentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    // Delegate to the underlying provider
    public event AuthenticationStateChangedHandler? AuthenticationStateChanged
    {
        add => _authenticationStateProvider.AuthenticationStateChanged += value;
        remove => _authenticationStateProvider.AuthenticationStateChanged -= value;
    }

    private void OnAuthenticationStateChanged(Task<AuthenticationState> task)
    {
        _authenticationStateTask = task;
    }

    private async Task OnPersistingAsync()
    {
        var authState = _authenticationStateTask ?? _authenticationStateProvider.GetAuthenticationStateAsync();
        var state = await authState;
        var principal = state.User;

        if (principal.Identity?.IsAuthenticated == true)
        {
            var email = principal.FindFirst(ClaimTypes.Email)?.Value
                        ?? principal.FindFirst(ClaimTypes.Name)?.Value;
            var roles = principal.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray();

            if (email is not null)
            {
                _persistentComponentState.PersistAsJson(nameof(UserInfo), new UserInfo
                {
                    Email = email,
                    Roles = roles
                });
            }
        }
    }

    // Required by IHostEnvironmentAuthenticationStateProvider
    public void SetAuthenticationState(Task<AuthenticationState> authenticationStateTask)
    {
        _authenticationStateTask = authenticationStateTask;
    }

    public void Dispose()
    {
        _subscription.Dispose();
        AuthenticationStateChanged -= OnAuthenticationStateChanged;
    }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_e8e96385e1b844f4b6e1825f7f37056e.Client;

/// <summary>
/// Client-side (WebAssembly) AuthenticationStateProvider that reads user info
/// from PersistentComponentState — data persisted by the server during prerendering.
/// This ensures auth state survives the transition from server to WebAssembly.
/// </summary>
public sealed class PersistentAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly Task<AuthenticationState> _unauthenticated =
        Task.FromResult(new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity())));

    private readonly Task<AuthenticationState> _authenticationStateTask;

    public PersistentAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        if (persistentState.TryTakeFromJson<UserInfo>(nameof(UserInfo), out var userInfo) && userInfo is not null)
        {
            var claims = new List<Claim>
            {
                new(ClaimTypes.Name, userInfo.Email),
                new(ClaimTypes.Email, userInfo.Email),
            };

            foreach (var role in userInfo.Roles)
            {
                claims.Add(new Claim(ClaimTypes.Role, role));
            }

            var identity = new ClaimsIdentity(claims, authenticationType: "Persisted");
            var principal = new ClaimsPrincipal(identity);
            _authenticationStateTask = Task.FromResult(new AuthenticationState(principal));
        }
        else
        {
            _authenticationStateTask = _unauthenticated;
        }
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _authenticationStateTask;
}

